function demoMain(idx,label){
  var layouts=[["header+sidebar+main",3],["navbar+hero+footer",3],["grid 3x3",9]];
  var l=layouts[idx%layouts.length];
  return "["+label+"] layout '"+l[0]+"' with "+l[1]+" regions, constraints satisfied";
}

